import json,re,datetime
try:
    s=json.loads(vars.get('state','{}'))
    today=datetime.date.fromisoformat(str(vars['now'])[:10])
    holidays={'2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01'}
    def business(d): return d.weekday()<5 and d.isoformat() not in holidays
    def forward(d):
        while not business(d): d+=datetime.timedelta(days=1)
        return d
    def after(n):
        d=today
        while n:
            d+=datetime.timedelta(days=1)
            if business(d): n-=1
        return d
    def dateval(t):
        t=str(t).strip().lower()
        if not re.fullmatch(r'[a-z0-9 /-]+',t): raise ValueError('date token')
        if t=='today': return today
        if t=='tomorrow': return today+datetime.timedelta(days=1)
        if re.fullmatch(r'\d{4}-\d{2}-\d{2}',t): return datetime.date.fromisoformat(t)
        if re.fullmatch(r'\d{1,2}[/-]\d{1,2}[/-]\d{4}',t):
            a,b,c=re.split(r'[/-]',t); return datetime.date(int(c),int(b),int(a))
        weekdays=['monday','tuesday','wednesday','thursday','friday','saturday','sunday']
        for i,w in enumerate(weekdays):
            if t in (w,'this '+w,'next '+w):
                return today-datetime.timedelta(days=today.weekday())+datetime.timedelta(days=i+(7 if t.startswith('next ') else 0))
        months=['january','february','march','april','may','june','july','august','september','october','november','december']
        m=re.fullmatch(r'(\d{1,2}) ([a-z]+)(?: (\d{4}))?',t)
        if m and m[2] in months: return datetime.date(int(m[3] or today.year),months.index(m[2])+1,int(m[1]))
        return None
    def spoken_number(text):
        text=str(text).lower().replace('-',' ').replace(',',' ')
        if text.strip().isdigit(): return int(text.strip())
        units=['zero','one','two','three','four','five','six','seven','eight','nine','ten','eleven','twelve','thirteen','fourteen','fifteen','sixteen','seventeen','eighteen','nineteen']
        tens={'twenty':20,'thirty':30,'forty':40,'fifty':50,'sixty':60,'seventy':70,'eighty':80,'ninety':90}
        ordinals={'first':'one','second':'two','third':'three','fourth':'four','fifth':'five','sixth':'six','seventh':'seven','eighth':'eight','ninth':'nine','tenth':'ten','eleventh':'eleven','twelfth':'twelve','thirteenth':'thirteen','fourteenth':'fourteen','fifteenth':'fifteen','sixteenth':'sixteen','seventeenth':'seventeen','eighteenth':'eighteen','nineteenth':'nineteen','twentieth':'twenty','thirtieth':'thirty'}
        total=0; part=0
        for token in text.split():
            token=ordinals.get(token,token)
            if token=='and': continue
            if token in units: part+=units.index(token)
            elif token in tens: part+=tens[token]
            elif token=='hundred': part*=100
            elif token=='thousand': total+=part*1000; part=0
            else: raise ValueError('number words')
        return total+part
    def security_raw(text,phase):
        text=str(text).lower().strip().strip('.')
        if phase=='phone':
            digits={'zero':'0','oh':'0','one':'1','two':'2','three':'3','four':'4','five':'5','six':'6','seven':'7','eight':'8','nine':'9'}
            if all(t in digits for t in text.replace('-',' ').split()): return ''.join(digits[t] for t in text.replace('-',' ').split())
            m=re.fullmatch(r'(?:the last four digits are |it is |it\x27s )?(\d{4})',text)
            return m[1] if m else ''
        text=re.sub(r'^(?:my date of birth is |i was born on |it is |it\x27s |the )','',text)
        months=['january','february','march','april','may','june','july','august','september','october','november','december']
        for i,month in enumerate(months):
            if re.search(r'\b'+month+r'\b',text):
                day,year=text.split(month,1); day=day.replace('of','').strip(); year=year.replace(',','').strip()
                tokens=year.split()
                if len(tokens)>=3 and tokens[0] in ('nineteen','eighteen','twenty') and 'thousand' not in tokens and 'hundred' not in tokens:
                    y=spoken_number(tokens[0])*100+spoken_number(' '.join(tokens[1:]))
                else: y=spoken_number(year)
                return datetime.date(y,i+1,spoken_number(day)).isoformat()
        dt=dateval(text)
        return dt.isoformat() if dt else ''
    def decode(text):
        lines=str(text).strip().splitlines()
        if not lines or lines[-1]!='END': raise ValueError('terminal')
        out=[]
        for row in lines[:-1]:
            d={}
            for part in row.split('|'):
                if part.count('=')!=1: raise ValueError('separator')
                k,v=part.split('=',1)
                if k not in ('k','p','a','d','c','v','t','scope') or k in d or not v: raise ValueError('tag')
                if any(x in v for x in ('[',']','{','}','"','\\')): raise ValueError('fragment')
                d[k]=v
            if not set(('k','c')).issubset(d) or d['c'] not in ('0','1'): raise ValueError('completion')
            if d['k'] not in ('yes','confirm','answer','proposal','no','vague','too_much','paid','dispute','partial','third','wrong_number','deceased','callback','decline','human','plan','hardship','stop','unknown'): raise ValueError('kind')
            if 'a' in d and not re.fullmatch(r'\d+(?:\.\d{1,2})?|full|total:\d+(?:\.\d{1,2})?',d['a']): raise ValueError('amount')
            if 'd' in d: dateval(d['d'])
            out.append(d)
        if not out: raise ValueError('empty')
        return out
    def resolve(ref):
        if ref in ('all','everything'): return s['products']
        refs=str(ref).split(','); out=[]
        for r in refs:
            r=r.strip().lower().replace('_',' ')
            matches=[p for p in s['products'] if r in (p['product_id'].lower().replace('_',' '),p['type'].replace('_',' '),p['label'].lower())]
            if len(matches)!=1: raise ValueError('reference')
            if matches[0] not in out: out.append(matches[0])
        return out
    def consent_terms(e):
        targets=[p for p in s['products'] if p['status']=='agreed'] if e.get('p','all') in ('all','everything') else resolve(e['p'])
        for p in targets:
            if 'a' in e:
                if e['a'].startswith('total:'): return False
                amount=p['past_due'] if e['a']=='full' else float(e['a'])
                if amount!=p.get('amount'): return False
            if 'd' in e:
                dt=dateval(e['d'])
                if dt is None or dt.isoformat()!=p.get('date'): return False
        return True
    def finish(outcome,reason='',text=''):
        s['outcome']=outcome; s['reason']=reason
        vars['outcome']=outcome; vars['reason']=reason
        return 'farewell',(text+' Thank you for your time. Goodbye.').strip()
    def question():
        phase=s['phase']
        if phase=='recipient': return 'Am I speaking with '+str(vars.get('title',''))+' '+str(vars.get('last_name',''))+'?'
        if phase=='dob': return 'What is your date of birth? Please say the month as a word.'
        if phase=='phone': return 'What are the last four digits of the phone number on file?'
        if phase=='callback': return 'When can the customer be reached, today or the next business day between 10:00 and 19:00?'
        if phase=='human': return 'May I help you first, or do you still want a human?'
        if phase=='support': return 'I am sorry you are going through this. Would you like me to connect you with customer support?'
        if phase=='confirm': return 'Please confirm all the payment terms I just read back, or give the correction.'
        for p in s.get('products',[]):
            if p.get('pending'):
                missing='amount' if not p['pending'].get('a') else 'exact date' if not p['pending'].get('d') else 'complete corrected terms'
                return 'Please finish the '+missing+' for your '+p['label']+'.'
        return 'Please clarify your latest decision for the named product.'
    def terms(p): return p['label']+', '+format(p['amount'],'.2f')+' on '+p['date']
    def offer(p,a,d,prefix=''):
        p['offer']={'amount':a,'date':d.isoformat(),'spoken':True}; p['status']='open'; s['current']=p['product_id']; s['phase']='offer'
        return 'speak',prefix+' Can you pay '+format(a,'.2f')+' for your '+p['label']+' on '+d.isoformat()+'?'
    def advance():
        for p in s['products']:
            if p.get('pending'):
                s['current']=p['product_id']; s['phase']='collect'
                missing='amount' if not p['pending'].get('a') else 'exact date' if not p['pending'].get('d') else 'complete corrected terms'
                return 'speak','Please finish the '+missing+' for your '+p['label']+'.'
        for p in s['products']:
            if p.get('refusal_pending') and not any(q.get('pending') for q in s['products']):
                p.pop('refusal_pending',None); return persuade(p)
        fresh=[p for p in s['products'] if p['status']=='open' and p.get('offer') and not p['offer'].get('spoken')]
        if len(fresh)>1:
            s['phase']='offer'; s['current']=fresh[0]['product_id']
            for p in fresh: p['offer']['spoken']=True
            return 'speak','Can you pay '+'; '.join(format(p['offer']['amount'],'.2f')+' for your '+p['label']+' on '+p['offer']['date'] for p in fresh)+'?'
        for p in s['products']:
            if p['status']=='open':
                s['current']=p['product_id']
                if p.get('offer'):
                    s['phase']='offer'; o=p['offer']; o['spoken']=True; return 'speak','Can you pay '+format(o['amount'],'.2f')+' for your '+p['label']+' on '+o['date']+'?'
                return persuade(p)
        agreed=[p for p in s['products'] if p['status']=='agreed']
        if agreed:
            s['phase']='confirm'; s['readback']=[(p['product_id'],p['amount'],p['date']) for p in agreed]
            return 'speak','Please confirm: '+'; '.join(terms(p) for p in agreed)+'. Do you confirm?'
        return commit_next()
    def persuade(p):
        p['attempts']+=1
        if p['attempts']>p['limit']:
            p['status']='refused'; return advance()
        if p['attempts']==1:
            d=today+datetime.timedelta(days=4-today.weekday())
            while not business(d): d-=datetime.timedelta(days=1)
            if d<=today:
                d=today-datetime.timedelta(days=today.weekday())+datetime.timedelta(days=11)
                while not business(d): d-=datetime.timedelta(days=1)
            d=min(d,datetime.date.fromisoformat(p['deadline']))
        else: d=datetime.date.fromisoformat(p['deadline'])
        a=p['floor'] if p.get('too_much') or p['attempts']==2 else p['past_due']
        return offer(p,a,d,'The rest stays overdue.' if a<p['past_due'] else '')
    def commit_next():
        for p in s.get('products',[]):
            if p['status']=='agreed':
                token=[p['product_id'],p['amount'],p['date']]
                if not s.get('verified') or s.get('transfer') or token not in s.get('consent',[]) or any(q.get('pending') for q in s['products']) or p.get('writes',0)>=2 or not p['floor']<=p['amount']<=p['past_due'] or not business(datetime.date.fromisoformat(p['date'])) or not today<=datetime.date.fromisoformat(p['date'])<=datetime.date.fromisoformat(p['deadline']): raise ValueError('write guard')
                vars['product_id']=p['product_id']; vars['amount']=p['amount']; vars['date']=p['date']; s['writing']=p['product_id']; p['writes']=p.get('writes',0)+1
                return 'create_promise',''
        for p in s.get('products',[]):
            if p['status']!='recorded' and not p.get('noted'):
                if not s.get('verified') or s.get('transfer'): raise ValueError('note guard')
                vars['product_id']=p['product_id']; vars['note_reason']=p['status']; s['writing']=p['product_id']; return 'add_note',''
        recorded=[p for p in s.get('products',[]) if p['status']=='recorded']
        if recorded:
            return finish('promise','', 'Your payment '+('promises are' if len(recorded)>1 else 'promise is')+' recorded. You will receive a text message confirming this promise.'+(' Some other products could not be recorded.' if any(p['status']=='service_error' for p in s['products']) else ''))
        nonpaid=[p for p in s.get('products',[]) if p['status']!='paid']
        return finish('no_promise',nonpaid[0]['status']) if nonpaid else finish('paid')
    route='speak'; line=''; prefix=''
    signal=vars.pop('signal','user')
    if not s:
        s={'phase':'recipient','recipient_asks':1,'declines':0,'stop':0,'human':0,'format':0,'verified':False,'products':[]}
        line='Hello, I am a digital assistant calling from Freya Bank, and this call is recorded. '+question()
    elif signal!='user':
        result_data=json.loads(vars.pop('api_data','{}')); d=result_data
        ok=str(d.get('ok','')).lower()=='true'
        if signal=='verify_identity':
            if d.get('hint')=='day_month_swapped' or not ok: line=question()
            elif str(d.get('all_verified','')).lower()=='true': s['verified']=True; route='get_account'
            elif str(d.get('verified','')).lower()=='true': s['phase']='phone'; line=question()
            elif int(d.get('wrong_answers_left',0))<=0: route,line=finish('not_verified','failed','Please use the mobile app or a branch.')
            else: line='That answer did not match. '+question()
        elif signal=='get_account':
            if not ok: route,line=finish('no_promise','service_error','I could not load the bank information.')
            else:
                products=d.get('products',[])
                if isinstance(products,str): products=json.loads(products)
                if not isinstance(products,list) or not 1<=len(products)<=3: raise ValueError('products')
                for p in products:
                    p['label']=p['type'].replace('_',' ')+(' ending '+str(p['card_last4']) if p['type']=='credit_card' else '')
                    p['floor']=float(p['minimum_payment'] if p['type']=='credit_card' else p['instalment_amount']); p['past_due']=float(p['past_due'])
                    p['limit']=1 if int(p['days_late'])<=7 else 2; p['deadline']=after(12 if p['limit']==1 else 7).isoformat(); p['attempts']=0; p['status']='open'
                s['products']=products; s['phase']='collect'; s['current']=products[0]['product_id']; s['initial']=True
                line='I am calling from the collections team about a late payment. '+' '.join('Your '+p['label']+' has '+format(p['past_due'],'.2f')+' past due and is '+str(p['days_late'])+' days late.' for p in products)+' Can you make all these payments today?'
                for p in products: p['spoken_full']=True
        elif signal=='create_promise':
            p=next(p for p in s['products'] if p['product_id']==s['writing'])
            if ok:
                p['status']='recorded'; route,line=commit_next()
            elif p['writes']<2: route,line=commit_next()
            else: p['status']='service_error'; route,line=commit_next()
        elif signal=='add_note':
            p=next(p for p in s['products'] if p['product_id']==s['writing']); p['noted']=True
            if not ok: s['note_failed']=True
            route,line=commit_next()
        elif signal=='schedule_callback': route,line=finish('not_reached','callback' if ok else 'no_callback','The callback is scheduled.' if ok else 'I could not schedule the callback.')
        elif signal=='transfer_to_agent': route,line=finish('transferred',s['transfer_reason'],'I am connecting you with the requested team.') if ok else finish('no_promise' if s['verified'] else 'not_verified','service_error' if s['verified'] else 'failed','I could not connect the call. Please contact customer service.')
    else:
        s['turns']=s.get('turns',0)+1
        if s['turns']>70: raise ValueError('bounded conversation')
        raw=str(vars.pop('raw_speech','')).strip(); low=raw.lower()
        admin=str(vars.pop('admin',''))
        if 'ai' in admin.split(','): prefix+="I am Freya Bank's digital assistant. "
        if 'scam' in admin.split(','): prefix+='You can verify this call by phoning Freya Bank customer service. '
        if 'unknown' in admin.split(','): prefix+='I do not have that information. '
        if 'purpose' in admin.split(',') and s.get('phase')=='recipient': prefix+='This is a private bank matter for the named customer. '
        try:
            events=decode(vars.pop('event',''))
            if s.get('verified'):
                for e in events:
                    if e['k'] not in ('human','plan','hardship','stop'):
                        resolve(e.get('p','all' if s.get('initial') else s.get('current','')))
        except Exception:
            s['format']+=1
            s['consent']=[]
            if s['format']>3: route,line=finish('not_verified' if not s['verified'] else 'no_promise','failed' if not s['verified'] else 'service_error','I could not safely understand the answer. Please contact the bank.')
            else: line=question()
            events=[]
        if events:
            s['format']=0; phase=s['phase']; first=events[0]; kinds=[e['k'] for e in events]
            unfinished=bool(re.search(r'\b(but|and|for|or|actually|instead|wait|correction)\s*$',low))
            if 'wrong_number' in kinds: route,line=finish('not_reached','wrong_number')
            elif 'deceased' in kinds: route,line=finish('not_reached','deceased','I am sorry for your loss.')
            elif 'plan' in kinds and 'hardship' not in kinds and any(e['k']=='plan' and e['c']=='1' and not (unfinished and e is events[-1]) for e in events):
                s['transfer']=True; s['transfer_reason']='restructuring'; vars['queue']='restructuring'; route='transfer_to_agent'
            elif ('human' in kinds and any(e['k']=='human' and e['c']=='1' and not (unfinished and e is events[-1]) for e in events)) or (phase=='human' and first['k']=='no' and first['c']=='1' and not unfinished):
                s['human']+=1
                if s['human']>=2 or phase=='human': s['transfer']=True; s['transfer_reason']='human'; vars['queue']='general'; route='transfer_to_agent'
                else: s['resume']=phase; s['phase']='human'; line=question()
            elif phase=='human': s['phase']=s.get('resume','recipient'); line=question()
            elif phase=='support' and (first['c']=='0' or unfinished or first['k']=='partial'):
                for e in events:
                    for p in resolve(e.get('p',s.get('current',''))):
                        pending=p.get('pending',{}).copy()
                        for tag in ('a','d'):
                            if tag in e: pending[tag]=e[tag]
                        pending['incomplete']=True; p['pending']=pending
                s['consent']=[]; s['phase']='collect'; route,line=advance()
            elif phase=='support' and first['k'] not in ('proposal','answer'):
                if first['k'] in ('yes','confirm'): s['transfer']=True; s['transfer_reason']='support'; vars['queue']='support'; route='transfer_to_agent'
                else:
                    for p in s['products']:
                        if p['status']=='open': p['status']='hardship'
                    route,line=advance()
            elif 'stop' in kinds:
                s['stop']+=1
                if s['stop']>=2:
                    if s['verified']:
                        for p in s['products']:
                            if p['status'] in ('open','agreed'): p['status']='refused'; p.pop('pending',None)
                        route,line=commit_next()
                    else: route,line=finish('not_verified','declined')
                else: line='I understand. '+question()
            elif phase=='recipient':
                if first['c']=='0' or unfinished: line='Please finish your answer. '+question()
                elif first['k']=='yes' or (first['k']=='answer' and (str(vars.get('last_name','')).lower() in low and str(vars.get('first_name','')).lower() in low)):
                    s['phase']='dob'; line=question()
                elif first['k']=='third': s['phase']='callback'; line=question()
                else:
                    s['recipient_asks']+=1
                    if s['recipient_asks']>2: route,line=finish('not_reached','unclear')
                    else: line=question()
            elif phase in ('dob','phone'):
                if first['c']=='0' or unfinished: line='Please finish your '+('date of birth.' if phase=='dob' else 'last four phone digits.')
                elif first['k'] in ('decline','no') or ('purpose' in admin.split(',')):
                    s['declines']+=1
                    if s['declines']>=2: route,line=finish('not_verified','declined')
                    else: line='These questions protect your account. '+question()
                else:
                    value=first.get('v','')
                    if not value:
                        try: value=security_raw(raw,phase)
                        except Exception: value=''
                    try:
                        if phase=='dob':
                            dt=dateval(value)
                            if not dt: raise ValueError('dob')
                            value=dt.isoformat()
                        elif not re.fullmatch(r'\d{4}',value): raise ValueError('phone')
                        vars['field']='date_of_birth' if phase=='dob' else 'phone_last4'; vars['answer']=value; route='verify_identity'
                    except Exception: line=question()
            elif phase=='callback':
                try:
                    dt=dateval(first.get('d','')); tm=first.get('t','')
                    if not dt or not re.fullmatch(r'\d{2}:\d{2}',tm): raise ValueError('callback')
                    when=datetime.datetime.fromisoformat(dt.isoformat()+'T'+tm)
                    if dt not in (today,after(1)) or not '10:00'<=tm<='19:00' or when<=datetime.datetime.fromisoformat(str(vars['now'])): raise ValueError('window')
                    vars['date']=dt.isoformat(); vars['time']=tm; route='schedule_callback'
                except Exception:
                    s['callback_errors']=s.get('callback_errors',0)+1
                    if s['callback_errors']>=2: route,line=finish('not_reached','no_callback')
                    else: line=question()
            elif s['verified']:
                if 'hardship' in kinds and not any(e['k']=='proposal' for e in events):
                    if any(e['c']=='0' for e in events) or unfinished: line='Please finish your answer.'
                    else: s['phase']='support'; line=question()
                elif phase=='confirm' and not unfinished and not re.search(r'\b(no|not|cannot|can\x27t|wait|instead|actually|change|but|except)\b',low) and all(e['c']=='1' and e['k'] in ('yes','confirm') and consent_terms(e) for e in events):
                    targets=[]
                    matching=True
                    for e in events:
                        scoped=([p for p in s['products'] if p['status']=='agreed'] if e.get('p','all') in ('all','everything') else resolve(e['p']))
                        targets+=scoped
                        for p in scoped:
                            if 'a' in e and (e['a']=='full' and p['amount']!=p['past_due'] or e['a']!='full' and (e['a'].startswith('total:') or float(e['a'])!=p['amount'])): matching=False
                            if 'd' in e and (dateval(e['d']) is None or dateval(e['d']).isoformat()!=p['date']): matching=False
                    agreed=[p for p in s['products'] if p['status']=='agreed']
                    if not matching:
                        s['consent']=[]
                        for e in events:
                            for p in (agreed if e.get('p','all')=='all' else resolve(e['p'])):
                                if 'a' in e or 'd' in e:
                                    p['pending']={'a':e.get('a',str(p['amount'])),'d':e.get('d',p['date'])}; p['status']='open'
                        route,line=advance()
                    elif set(p['product_id'] for p in targets)!=set(p['product_id'] for p in agreed) or any(p.get('pending') for p in s['products']): line='Please confirm all the terms together, or tell me the correction.'
                    else: s['consent']=s['readback']; route,line=commit_next()
                else:
                    # Resolve every sibling before modifying any target; one bad sibling blocks the whole event.
                    resolved=[]
                    for e in events:
                        ref=e.get('p','all' if s.get('initial') else s.get('current',''))
                        targets=resolve(ref)
                        if phase=='offer' and ref in ('all','everything') and e['k'] in ('yes','confirm'): targets=[p for p in targets if p.get('offer',{}).get('spoken')]
                        if not targets: raise ValueError('unspoken offer')
                        resolved.append((e,targets))
                    s['consent']=[]; warnings=[]
                    if 'hardship' in kinds:
                        volunteers=set(p['product_id'] for e,ts in resolved if e['k']=='proposal' for p in ts)
                        for p in s['products']:
                            if p['status']=='open' and p['product_id'] not in volunteers: p['status']='hardship'
                        warnings.append('I am sorry you are going through this.')
                    for e,targets in resolved:
                        total=e.get('a','').startswith('total:')
                        if total and float(e['a'][6:])!=sum(p['past_due'] for p in targets):
                            line='Please allocate that total to each named product.'; break
                        for p in targets:
                            k=e['k']
                            if k=='hardship': continue
                            if p['status']=='recorded': warnings.append('A recorded promise cannot be changed here; use the mobile app.'); continue
                            if p['status']=='paid' and k in ('paid','no'): continue
                            if e['c']=='0' or (unfinished and e is events[-1]) or k=='partial':
                                pending=p.get('pending',{}).copy()
                                for tag in ('a','d'):
